    "question": "国際関係における主要な考え方に関するア～オの記述のうち、主にリベラリズムについて述べた記述として妥当なもののみを全て挙げているのはどれか。\nア　世界は基本的に国々の行動を統制する権威が存在しないアナーキーではあるものの、国家間の同盟により競合する勢力間の力の均衡が保たれている場合、特に二つの超大国が並び立つ二極体制の場合には、秩序を安定的に保つことが可能である。\nイ　民主主義国では議会や世論、メディアなどの役割が大きく政治指導者の恣意的な決定が妨げられ、暴力ではなく話し合いで利害対立を解決すべきという規範が働く。それゆえ民主主義国どうしは戦争をしにくいと考えられる。\nウ　世界経済における格差は構造的なものであり、一次産品を輸出する「周辺」に位置する途上国は貿易赤字が継続し、「中心」に位置する先進国との格差は拡大しがちである。\nエ　「自由な貿易は平和に結び付き、高率関税、貿易障壁、不公平な経済競争は戦争に結び付く」という有名な言葉があるように、自由貿易は国際関係を協調的、平和的なものにする効果があると考えられる。\nオ　特定の国のリーダーシップが十分発揮されない場合においても、国際制度を通じたルールの制定や普及を通じ、協調的な国際関係を保つことは可能である。",
