      "ア": "有力な政治家により掲げられた政策のアイディアがその後の政策形成に影響を及ぼすことがあり、そのような政策のアイディアをC. リンドブロムは政策遺産と表現した。政策形成過程において過去の政策遺産が政治家の支持基盤を強固にし、選挙での再選を有利にする現象をロックイン効果という。また、政策遺産とそのロックイン効果から、過去の政治的支持基盤が現在へと継続される現象は経路依存性と称される。",
