      "エ": "憲法第95条には首長・議員の解職に関する住民投票の規定がある。地方公共団体の住民は有権者の50分の1以上の署名を集めることで解職に関する住民投票を請求し、住民投票で有権者の過半数が同意すれば首長・議員を解職することができる。また、地方自治法には条例の制定・改廃に関する住民投票の規定がある。住民投票で有権者の過半数が同意すれば、首長・議会は投票結果に従い条例を制定・改廃しなければならない。",
