    "difficulty": 3,
    "question": "国家領域及び海洋法に関するア～オの記述のうち、妥当なもののみを挙げているのはどれか。\nア　領海は、沿岸国の領域主権に服するものの、外国船舶には無害通航権が認められている。無害通航権の行使に際して、通航は継続的かつ迅速に行われなければならず、停船及び投びょうは、航行に通常付随する場合や、危難を避ける場合などに例外的に認められる。潜水船にも無害通航権は認められるが、その際には海面上を航行しなければならない。\nイ　国連海洋法条約（注1） は、公海又は排他的経済水域の一部分と公海又は排他的経済水域の他の部分との間にある国際航行に使用される海峡において、全ての国の船舶及び航空機に対して、通過通航権を認めている。しかし、当該権利は、もともと領海である海域に設定されている権利であるため、通過通航中の船舶が海峡沿岸国の法令に違反する場合には、その海峡沿岸国は当該船舶の通過通航を一時的に停止することができると同条約は規定している。\nウ　特段の事情がない場合、領域国の許可なく外国航空機が領空に立ち入ることは領空侵犯とみなされる。領域国は、警告などの適切な防止措置を講じてもなお領空侵犯が継続する場合には、必要な対抗措置を採ることができると一般に解されている。ただし、民間航空機による領空侵犯については、シカゴ条約（注2） の追加条項において、武器の使用に訴えることを差し控えることが規定されている。\nエ　島の集団又はその一部、相互に連結する水域その他天然の地形が本質的に一つの地理的、経済的及び政治的単位を構成しているか又は歴史的にそのような単位と認識されているものを群島と呼ぶ。群島から成る国では、領海の範囲を定めるに当たり、群島を構成する全ての島がその内部に収まる最小の円を基線とすることが、国連海洋法条約により認められている。\nオ　沿岸国の権限ある当局は、自国の内水、領海又は接続水域において、外国船舶が当該水域について適用される自国の法令に違反したと信じるに足りる十分な理由がある場合、各海域で開始した当該外国船舶に対する追跡を公海において継続することができる。ただし、当該外国船舶が他国の接続水域に入った時点で、その追跡の権利は消滅する。\n\n（注1）国連海洋法条約とは、「海洋法に関する国際連合条約」（1982年採択）を指す。\n（注2）シカゴ条約とは、「国際民間航空条約」（1944年採択）を指す。",
