    "question": "国際安全保障に関するア～エの記述のうち、妥当なもののみを全て挙げているのはどれか。\nア　The Charter of the United Nations provides that decisions on procedural matters shall be made by an affirmative vote of nine members, while decisions on all other matters shall be made by an affirmative vote of nine members including the concurring votes of the permanent members.\nイ　In the Nicaragua case*1,the International Court of Justice held that, as a requirement under customary international law for exercising the right of collective self-defense, a State subjected to an armed attack must itself declare that it has been attacked: however, it is not required that the attacked State request other states to exercise the right of collective self-defense.\nウ　Additional Protocol I to the Geneva Conventions*2 stipulates that facilities containing dangerous forces, such as dams and nuclear power plants, shall not be made the object of attack, even where these facilities are military objectives, if such attack may cause the release of dangerous forces and consequent severe losses among the civilian population.\nエ　The Rome Statute*3 lists the crime of aggression as one of the crimes within the jurisdiction of the International Criminal Court. However, a clear definition of acts of aggression has yet to be established under international law, and no document defining aggression has been adopted by international organizations, including the United Nations.\n\n（注）\n*1 Nicaragua case: International Court of Justice, Military and Paramilitary Activities in and against Nicaragua (Nicaragua v. United States of America), Merits, Judgment of 27 June 1986\n*2 Additional Protocol I to the Geneva Conventions: Protocol Additional to the Geneva Conventions of 12 August 1949, and relating to the Protection of Victims of International Armed Conflicts (Protocol I), adopted on 8 June 1977\n*3 Rome Statute: Rome Statute of the International Criminal Court, adopted on 17 July 1998",
