    "question": "環境倫理・環境思想に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "学問としての環境倫理学は、1950年代に地球の温暖化が確認されたことによって始まった。初期の環境倫理学では、様々な環境問題の原因は、近代文明がキリスト教的世界観を否定した結果、自然科学と科学技術が無条件に是認され、人間が自然を支配することが肯定されたことにあるという見解が唱えられた。そして、そのような人間中心主義的な思想を批判する、人間非中心主義的な環境倫理の理論が提唱された。",
      "イ": "環境倫理の理論には、人間だけでなく、動物やその他の自然物に対しても倫理的配慮をすべきとするものがあり、それは幾つかの種類に分かれる。苦痛を感じるあらゆる動物に倫理的配慮をすべきとする理論、苦痛を感じるか否かに関わらず生命を持つあらゆるものに倫理的配慮をすべきとする理論、生態系全体に倫理的配慮をすべきとする理論などである。",
      "ウ": "動物解放論は、快苦を感じる感覚能力を根拠として、動物の権利を主張している。そして、その主張は、動物を個体として尊重するものであるが故に、生態系の存続や生物多様性などの重要課題に対応できるものとして発展した。他方、生態系の存続や生物多様性を重視する理論の中には、生態系のようなシステム全体のために個体を犠牲にすることを容認する「環境レイシズム」として批判されるものがある。",
      "エ": "動物のみならず、その他の自然物にも権利を認める理論もある。例えば、アメリカでは、1970年代に自然を破壊する開発に反対する訴訟が起こされ、自然物にも裁判で原告となる権利があるとする法学的見解も現れた。ナショナル・トラスト運動も、自然物の権利を法的に認めるために始まったものである。しかし、権利概念が過剰に拡張されたとの反省から、現在では、動物以外の自然物の権利は、アメリカでも法的には認められていない。",
      "オ": "環境問題を、人間と自然との関係からではなく、人間と人間との関係から捉える環境倫理の理論もある。例えば、環境汚染・破壊が人種差別や政策上の不公正に深く関わっていることが認識されるようになり、その克服を目指す運動から「種差別」という概念が生まれた。また、環境問題は親の世代と子供の世代が話し合って解決すべきだとする理論もあり、これは「世代間倫理」と呼ばれる。"
    },
