    "choices": {
      "ア": "帝国主義時代のアフリカでは、イギリスとフランスに主導された「アフリカの分割」と呼ばれる状況が進行した。とりわけ、大陸の横断政策を採ったイギリスと、縦断政策を採ったフランスの両軍がスーダンで衝突したが、フランスがモロッコを確保することで妥協が成立した。モロッコはその後、モロッコ事件を経てフランスの保護国となったが、「アフリカの年」として知られる1956年に独立を果たした。",
      "イ": "ポルトガルは、15世紀にアフリカ西岸やインド洋への航路をいち早く確立した。16世紀にはマニラを占領し、これを中国との交易の拠点としたほか、ラテンアメリカではブラジルに植民地を展開した。ナポレオン戦争下でヨーロッパの本国が動揺した結果、中南米の各地で独立の気運が高まると、ブラジルのムラートと先住民は、本国からの干渉の復活や奴隷制廃止の強制を恐れ、王太子を擁立してブラジル帝国を成立させた。",
      "ウ": "スペインから独立したオランダは、17世紀にバタヴィアに要塞を築き、ジャワ島を中心に東南アジア交易を展開した。しかし、商業覇権に陰りがみえた18世紀には、植民地経営に路線を転向した。こうして形成されたオランダ領東インドは、ナポレオン戦争期に統治体制が崩壊し、イギリス軍によって一時占領されたが、間もなくオランダによる支配が回復した。20世紀には、スカルノの指導下で独立を目指す運動が広まった。",
      "エ": "ドイツでは、ヴィルヘルム1世と宰相ビスマルクの下で「世界政策」が推進された。19世紀末には、バグダード鉄道の敷設権を獲得してオスマン帝国と対抗し、カメルーンや東アフリカの一部の植民地化を進めた。同じ頃、ベルギーによるコンゴ領有宣言を契機に、ビスマルクの仲介によってベルリン会議が開かれ、その結果、最初に占領した国に領有権を認める「先占権」が承認され、ヨーロッパ諸国によるアフリカ分割が進んだ。",
      "オ": "工業化や資本輸出によって力を付けたイギリスは、世界経済の中心としての地位を維持し、広大な植民地帝国を形成した。最盛期を迎えたヴィクトリア女王治世下では、インド帝国を成立させ、また、アルジェリアを事実上の保護国とした。他方で、帝国の結束を固めるため、白人中心の植民地には自治権を与える政策が推進され、アイルランドを皮切りに、カナダやオーストラリア、ニュージーランドが相次いで自治領となった。"
    },
