    "question": "日本の物語文学に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "平安時代に書かれた、架空の人物・事件を物語った作品を、作り物語という。代表的な作り物語は、全54帖から成る長編物語「源氏物語」であるが、その「絵合」巻で「物語の出で来はじめのおや」とされているのは「落窪物語」である。「竹取物語」、「宇津保物語」なども「源氏物語」より前に成立したとされる。また、「堤中納言物語」は短編物語集で、男女が入れ替わる「とりかへばや物語」を含んでいる。",
      "イ": "主に平安時代において、和歌を中心にまとめられた短い物語や、それらを集めた物語集を、歌物語という。「伊勢物語」では、各段の多くは「昔、男ありけり」という書き出しで、主人公は六歌仙の一人であり、色好みの美男子として知られた在原業平をモデルにしているとされる。「平中物語」は、平中と呼ばれた平貞文（定文） を主人公とした恋物語を集めたものである。他に「大和物語」も、この時代の歌物語である。",
      "ウ": "主に平安時代から鎌倉時代にかけて書かれた、歴史的事実を物語風に叙述した作品を、歴史物語という。「栄花（栄華）物語」は大宅世継・夏山繁樹の二老人が昔語りをする形式で、藤原道長・頼通の栄華を中心とした歴史を編年体で記したものである。また、「大鏡」は、藤原清衡・基衡・秀衡の栄華を中心とした歴史を紀伝体で記したものである。「大鏡」は鏡物の最初で、「今鏡」「水鏡」「増鏡」と合わせて四鏡ともいう。",
      "エ": "鎌倉時代から室町時代にかけて書かれた、武士集団の戦闘を主題として時代や人物を叙事的に描いた作品を、軍記物語という。文体の多くは和漢混交文である。「平家物語」は、平家一門の興亡に焦点を当て、勇壮な合戦を描写するとともに不易流行の思想も語る。「太平記」は、南北朝時代の内乱を描き、主に琵琶法師によって語り広められたことも知られる。他に「保元物語」「平治物語」も軍記物語である。",
      "オ": "神話・伝説・昔話・世間話など、人から人へ伝えられてきた物語を説話といい、これらを集めた作品を説話集という。平安初期の『懐風藻」は、日本で最も古い仏教説話集である。平安後期の説話集である 「今昔物語集」は、インド、中国など異国の説話のみを集め、教訓性の強い説話が多いことが特徴である。鎌倉初期の説話集である「宇治拾遺物語」は、貴族説話、仏教説話、民間説話などを収め、この時代の人々の生活感情を伝えている。"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "和歌を核とする歌物語には、在原業平が主人公のモデルとされる『伊勢物語』や、平貞文を中心とする『平中物語』、『大和物語』がある。",
