      "イ": "和歌を核とする歌物語には、在原業平が主人公のモデルとされる『伊勢物語』や、平貞文を中心とする『平中物語』、『大和物語』がある。",
      "ウ": "大宅世継と夏山繁樹が語る形式は『大鏡』に見られる。藤原道長らの栄華を中心に編年体で語るのは『栄花物語』である。",
      "エ": "『平家物語』には諸行無常の思想が表れ、琵琶法師の語りでも伝えられた。『太平記』は南北朝の内乱を描くが同じ伝承形式とはいえない。",
      "オ": "『懐風藻』は漢詩集で、古い仏教説話集には『日本霊異記』がある。『今昔物語集』はインド、中国に加えて日本の説話も収める。"
