      "イ": "関ヶ原の戦いの後に佐和山城を与えられたのは井伊直政である。彦根城天守の移築元としては大津城が有力とされる。",
      "ウ": "姫路城を現在の規模に拡張したのは池田輝政である。白漆喰の美しさから白鷺城と呼ばれ、乾小天守が現存最大の天守という説明も誤りである。",
      "エ": "犬山城は木曽川沿いにあり、金華山にあるのは岐阜城である。成瀬家の個人所有を経て、現在は財団が所有している。",
