      "イ": "現代の狩猟採集民の多くは貨幣経済に関わり、新しい技術も利用する。狩猟と獲物の分配には、文化や社会関係を保つ役割もある。",
      "ウ": "シマウマは一般的な家畜に含まれない。高地と低地など決まった場所を季節的に移動する牧畜は移牧と呼ばれる。",
