    "difficulty": 3,
    "question": "教育基本法に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\nA　教育基本法の前文では、教育の目指す理想を掲げるとともに、「個人の尊厳」や「公共の福祉」の尊重等が掲げられている。戦前及び戦時中には、教育の基本理念が世の中に広く示されることはなかったが、終戦後、愛国教育、軍国主義教育から転換したことを際立たせるため、教育基本法制定時に前文が置かれた。\nB　教育基本法第3条では、生涯学習の理念が掲げられているが、同条は平成18年の改正によって新設されたものである。昭和61年の教育改革に関する臨時教育審議会の答申 * では、学習者の主体性を明確にするため、それまで使用されていた「生涯教育」に代わり、「生涯学習」という用語が用いられた。\nC　教育基本法第14条では政治教育について規定しているが、平成27年に公職選挙法が改正されて選挙権の対象が18歳以上へと引き下げられたことから、18歳以上の生徒による、学校の構内での選挙運動や政治的活動については、学校が制限又は禁止することは一切できない。また、教員が、18歳以上の生徒に対して党派的な教育を行うことが認められている。\nD　教育基本法第15条では、学校における政教分離の原則について規定しているが、国公立学校であっても、学校の設置者が必要であると認めるときは、特定の宗教のための宗教教育を行うことができる。また、宗教法人が設置する私立学校においては、宗教教育を行う際は、児童生徒の思想・良心の自由に反しないよう努めることとされている。\n\n* 教育改革に関する第二次答申（昭和61年4月）",
