    "difficulty": 3,
    "question": "教育における心理的効果に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\nA　ハロー効果とは、他者がある側面で望ましい（又は望ましくない） 特徴をもっていると、その評価を当該人物に対する全体的評価にまで広げてしまう傾向のことである。例えば、教師が生徒をみる場合、成績の良い生徒は性格面や行動面でも肯定的に評価されがちであるのに対して、成績の悪い生徒は全ての面で問題があるかのようにみられやすい。\nB　ピグマリオン効果とは、B.F. スキナーによって提唱された、他者に対してもっている期待が成就されるように機能する傾向のことである。例えば、教師が期待している学習者に対しては、学習者への働きかけや学習者自身の意欲にかかわらず、教師が学習者の今後の成績向上を見込んで、実際の評価以上の評価を与えてしまうことがある。この効果は、教師期待効果とも呼ばれるが、このような仕組みは、意識的なららのであることが多い。\nC　学習転移とは、刺激の提示順序に応じて、記憶の成績が異なる現象のことである。リスト形式で提示された材料を記憶・学習する場合、リストの冒頭部で提示された項目の成績が優れていることを初頭効果、終末部で提示された項目の成績が優れていることを新近性効果という。また、リストを記憶後に休息をとることで、内容が脳内で整理され、刺激の提示順序による影響を受けなくなることを、スリーパー効果という。\nD　ブーメラン効果とは、説得の効果のうち、内容が及ぼす効果が時間の経過に伴って増加することである。例えば、教師が予習・復習の大切さを説いた際、最初は生徒に反発されても、時間が経つと生徒が自ら納得するようになることを指す。説得に失敗する要因としては、受け手自身の立場へのコミットメントや話題への自我関与が低い場合などがある。",
