    "question": "貧困や子どもの貧困に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\nア　貧困に関する社会調査には、19～20世紀英国におけるC. ブース、B. S. ラウントリーらの貧困調査、明治・大正期の我が国における横山源之助らの下層社会調査、今日の産業国・開発途上国の貧困調査等、多くの蓄積がある。横山源之助は、東京の貧民や職人、手工業や機械工場の労働者、小作人の状態を、これらの側に立って調査・分析し、下層社会を社会構造の中に位置付けた「日本之下層社会」を刊行した。\nイ　貧困を定義する際に一般的に用いられる概念が、「絶対的貧困」と「相対的貧困」 である。絶対的貧困とは、生存のための最低生活費を下回る収入や生活費の状態のことをいう。それに対して、相対的貧困とは、社会の一員として生活するための最低限の水準を下回る状態を指す。厚生労働省等の統計で使用される相対的貧困率は、等価可処分所得（所得から所得税や住民税、社会保険料等を差し引き調整した額） の平均値の半分に満たない世帯の割合を表す。現在の我が国の生活保護費の基準は、絶対的貧困概念を基にしている。\nウ　「2022（令和4） 年国民生活基礎調査」（厚生労働省） によれば、令和3年の我が国の子どもの貧困率は約16% と算出されており、約6人に1人が貧困世帯の子どもとなる。平成24年の子どもの貧困率は約12% で、約8人に1人が貧困世帯の子どもであり、その割合は増加している。また、令和3年において、子どもがいる現役世帯のうち、大人が2人以上いる世帯は子どもの貧困率が約12% であるのに対して、大人が1人の世帯の子どもの貧困率は約55% に及んでいる。\nエ　子どもの貧困の背後には、母子世帯の存在もあるといわれている。「令和3年度全国ひとり親世帯等調査」（厚生労働省） によれば、全国の母子世帯は約120万世帯と推計されている。母親の就業率は約86% であり、母子世帯の多くの母親が就業している。しかし、母親の平均年間就労収入は236万円にとどまっており、世帯全員の平均年間収入も373万円にとどまっている。児童のいる世帯全体の平均年間収入は813.5万円であるため、これと比べると大きな開きがある。",
