      "オ": "災害関連死とは、地震による建物の倒壊や津波などによる直接的・物理的な原因ではなく、災害による負傷の悪化や避難生活等の身体的負担による疾病により死亡することを指し、平成28年4月に発生した熊本地震では、災害関連死が地震による直接の死者数を上回っている。"
