      "イ": "インフォームド・コンセントとは、医師が患者に対して、治療法の危険性や費用等の利害について十分な説明を行い、患者がそれを理解した上で、自由意思に基づき治療法に同意することである。この条件が満たされるとき、インフォームド・コンセントの理念に基づくならば、医師がより安全と考える治療法とは異なる治療法を患者が選択したとしても、患者の選択を尊重することが求められる。",
