      "ウ": "宋代の地主層は、儒学の教養を身に付けた知識人でもあった。宋代の儒学では、哲学的な議論よりも経典の厳密な校訂・検証を行う考証が盛んとなり、また、華夷・君臣・父子の区別といった社会秩序も重視された。南宋の王陽明によって大成された宋学は、儒学の正統とみなされるとともに、中国のみならず日本や朝鮮にも大きな影響を与えた。",
      "エ": "18世紀の清朝では、爆発的な人口増加によって国内移住が増加し、山間部の開発が進んだが、開発が限界に達すると社会不安が高まった。この結果、19世紀半ばには、広西の太平天国や陝西・甘粛・雲南の回民による反乱が起こった。清朝の正規軍ではこれらに十分に対処できなかったため、地主層は、自衛のために団練や郷勇と呼ばれる義勇軍を編成した。",
