      "エ": "資本主義を批判するマルクスとエンゲルスの経済理論及び社会思想は、歴史学にも大きな影響を与えた。「共産党宣言」で知られる彼らは、生産力と生産関係を基礎とする「下部構造」（「土台」） が、法律・政治・思想などから成る「上部構造」を規定し、生産力と生産関係との間に発生する矛盾によって歴史が進行する、とする唯物史観を提示した。",
