    "question": "仮名の発生とその展開に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "万葉仮名とは、上代に日本語を表記するために用いた漢字のことで、真正の文字（真名） である漢字から、その音や訓を仮借したもの（仮名） をいう。最初の勅撰和歌集である 「万葉集」では、日本語の音形を書き留める必要から仮名が多用され、やがて万葉仮名と呼ばれるようになった。また、漢文表記を主とする「古事記」とは異なり、「日本書紀」でも万葉仮名が多く用いられた。",
      "イ": "平安初期には、勅撰漢詩集「凌雲集」が編まれるなど五山文学が盛んであったが、やがて漢字を草体化した平仮名や、略体化した片仮名が用いられるようになった。特に平仮名は、女性が歌や手紙を記すのにしばしば用いたことから発達し、紀貫之が女性に仮託して書いた「蜻蛉日記」に平仮名を用いて以降、和歌、物語、日記、随筆など、様々な文学ジャンルが仮名表記によって発展した。",
      "ウ": "同音の仮名の使い分けの決まりを仮名遣いという。鎌倉時代に藤原定家が示した定家仮名遣いは、誤読を避ける目的で表記を一定にするものである。明治時代に歴史的仮名遣いとされたのは、万葉仮名を基準にした、室町時代の契沖による「和字正濫鈔」の方式によるものであった。昭和20年代に現代仮名遣いが公布されたが、大江健三郎や丸谷才一のように、あえて歴史的仮名遣いを引き続き用いる作家もいた。",
      "エ": "現在使用されるものと異なる字体の仮名を変体仮名といい、一般に複数の字体が併用された。木版印刷が発達した江戸時代には、挿絵入りの仮名書き読み物である草双紙が生まれ、筆書きの文章と絵とが一体となった刊本が流行した。恋川春町による「金々先生栄花夢」などが代表作で、子供向けの赤本をはじめ、黒本、青本、黄表紙、合巻と展開した。学校教育で仮名の字体が統一されたのは明治時代である。",
      "オ": "活版印刷が主流となった明治時代には、大衆的な新聞は、原則全ての漢字に振り仮名を付す総ルビで印刷された。例えば、「読売新聞」に連載された夏目漱石の小説は、「吾輩は猫である」、『坊っちゃん」をはじめ、原則総ルビである。一方、昭和になると、「恩讐の彼方に」、「父帰る」などで知られる小説家・劇作家の山本有三は、振り仮名がなくても読める文章を書くのが良いとして、「ふりがな廃止論」を唱えた。"
    },
