      "イ": "セルバンテスはスペインの詩人である。代表作「ドン・キホーテ」では、美しいカターイ（中国） の王女を追って、主人公をはじめ、キリスト教徒、異教徒の騎士たちがそれぞれに諸国を放浪して戦い、さらに幾組もの恋人たちが交錯する。恋のために発狂して、風車を巨人とみなすなどの主人公のエピソードを中心に、恋と武勇と魔法の奔放自在な空想物語が、洗練された8行韻詩で語られる。失われた騎士道の理想を懐かしみつつ語る点に物語の特徴がある。",
