    "choices": {
      "ア": "長谷川等伯は、能登七尾出身の絵師である。武士の子に生まれるが、絵仏師の系譜に連なり、当初は信春と号した。明兆流を皮切りに、その源流である明・清の水墨画を学び、有力寺院や織田信長、豊臣秀吉関連の建築物に多くの作例を残した。その代表作「唐獅子図屏風」は和風水墨画の極致として高く評価され、また、祥雲寺障壁画（現・智積院障壁画） には、やまと絵様式を融合した豊潤な金碧障壁画を描いた。",
      "イ": "狩野永徳は、室町期武士を祖とする狩野派の絵師である。20歳代のうちから画才で頭角を現し、戦国期の武将好みの豪壮で力強い画風を展開した。特に織田信長からは手厚い庇護を受け、その新たな居城である岐阜城の障壁画制作を委ねられたが、それらは後に焼失した。現存するのは、信長が上杉謙信に贈った『富士三保図屏風」や「檜図屏風」で、これらのほか、大徳寺や南禅寺に伝わる障壁画群も非常に名高い。",
      "ウ": "海北友松は、近江の武家浅井家の家臣の子である。浅井家滅亡時には、禅修行先の東福寺で難を逃れ、後に還俗して絵師としての道を歩んだ。中国宋元画、中でも梁楷の減筆体に多くを学び、袋人物と呼ばれる描法を得意とした。他方で、やまと絵様式の彩色画も描くなど幅広い多様な画業を展開し、公武の有力な貴族たちに支持され、とりわけ、晩年は宮廷御用となって、皇族や公家のために多く作画した。代表作に「浜松図屏風」や「網干図屏風」などがある。",
      "エ": "雲谷等顔は、肥前の高位の武家の子である。一族没落の後、戦国武将の蜂須賀正勝（小六） に絵師として抱えられ、同家に伝わる画僧周文の作例「山水長巻」などに学んだ。その後優れた画才が認められ、周文の旧居でアトリエでもあった雲谷庵を受け継ぐとともに、雲谷姓を名乗り、周文三代を自称した。その生涯にわたり、蜂須賀家御用絵師として狩野派や長谷川派と画技を競い、ほぼ水墨画の制作に傾注した。代表作に「山水図屏風」や]|『竹林七賢図屏風』|] などがある。",
      "オ": "曽我直庵は、越前の武将の子孫と伝えられる絵師である。一族の没落後に堺へ出て、京都や奈良、高野山の有力寺院の求めに応じて作画した。漢画系ながら中国ではなく朝鮮の絵師を祖とすると言われており、画僧雪舟の画風を伝えた室町期の絵師である曽我蛇足の末流と自称した。作例のほとんどが粗豪な筆致による水墨画で、主題は花鳥や山水で占められており、代表作には、豊臣秀頼が北野天満宮に奉納した『洛中洛外図屏風」のほか、「松柏に鷹図屏風」などがある。"
    },
