    "question": "日本の中世を代表する古窯に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "常滑焼は、現在の愛知県の窯で作られている。窯跡は知多半島の広範囲にわたって存在し、古墳時代に始まった猿投窯の流れを受け継いでいる。遅くとも平安後期には開窯し、甕や鉢、茶碗などが確認される。中世に入ると、畿内有力寺院の瓦も製造するなど、製品はほぼ全国各地で用いられた。後に、鉄分の多い粘土から作る朱泥の茶陶器も人気を博した。現在は、陶製の土管やタイル、植木鉢なども多く生産している。",
      "イ": "越前焼は、現在の福井県の窯で作られている。もともと、丹生山地一帯では須恵器生産が行われていたが、平安末期頃に関東地方の窯産地の技術を導入し、酸化焔焼成の越前焼が生まれた。中世には北陸地方最大の窯業地として、人工釉による壺や甕などを数多く生産した。遠く北海道地方や山陰地方でも使用され、後には鉄衝も施すようになるが、近世に入ると他窯が活発となり、地方窯として主に日常雑器を生産した。現在も、高温焼成による良質な三州瓦で知られる。",
      "ウ": "備前焼は、現在の岡山県の窯で作られている。古墳時代には須恵器の産地であったが、平安末期頃に酸化焔焼成による焼締め陶生産へと転換した。その初期には表面が茶色を呈したものの、鎌倉後期には著名な黒褐色の焼き物となった。無施釉の陶器として、流水紋などの自然に現れる味わい深い文様が有名である。当初の地方窯から、南北朝期以降は商業圏を次第に拡大し、他方で早くから喫茶の茶器を焼いたことも記録される。",
      "エ": "瀬戸焼は、現在の岐阜県の窯で作られている。古墳時代に始まった猿投窯の流れを汲んで、平安後期から鎌倉初期頃には開窯したとされ、往時は施釉による唯一の焼き物であった。中世には灰釉のほか鉄釉も行い、盛期を迎えた。やがて、戦火を逃れた多くの陶工らが美濃に移住したとされ、その後も、瀬戸では引き続き茶器や日常雑器を製造したものの、他窯に押され、江戸後期にはガラス器生産も開始した。瀬戸物といえば、現在でも焼き物の代名詞となっている。",
      "オ": "信楽焼は、現在の三重県の窯で作られている。それ以前に同地で焼かれた須恵器とは異なり、平安末期から鎌倉初期頃に新たに作られた焼締め陶のことを指す。無施釉が基本で、その地肌は赤褐色を呈し、素地に多く含まれる長石の粒が器面に現れるのを特色とする。室町後期からは茶の湯の茶器としても愛されたが、現在では、各種の食器のほか、タイルや植木鉢も多い。また、信楽焼では一般に、狐の置物が広く世に知られる。"
    },
    "answer": "ア",
    "officialAnswerNumber": 1,
    "explanation": "常滑焼は知多半島に展開した猿投窯の系統の焼き物である。中世の壺や甕の広い流通、後世の朱泥の茶器や土管などが知られる。",
