      "イ": "越前焼の成立には常滑焼の技術が影響した。現在、三州瓦という名称で知られる瓦の産地は愛知県の三河地方にある。",
      "ウ": "備前焼は釉薬を使わない焼締めで、焼成時の条件によって緋襷や胡麻などの模様が現れる。流水紋を主な特徴として挙げる点が適切ではない。",
      "エ": "瀬戸焼の中心産地は愛知県瀬戸市である。美濃でも瀬戸の技術が伝わったが、瀬戸と美濃は区別される。",
      "オ": "信楽焼の産地は滋賀県甲賀市信楽町である。信楽焼の置物として特に広く知られるのはタヌキである。"
