    "difficulty": 3,
    "question": "パーソナリティの理論に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\nア　C. G. ユングは、人間には、心的エネルギーの向かう方向によって、内向一外向という二つの根本的態度があることに加え、四つの心理的機能として思考、感情、感覚、直観の区別を考えた。そして、根本的態度と心理的機能の組合せから八つの基本類型を想定した。心理的機能のうち、思考と感情、感覚と直観は対立関係にあり、個人が主として依存しているものを優越機能、その対立機能を劣等機能と呼ぶ。\nイ　A. アドラーは、個人心理学 (individual psychology) という理論体系を創始した。個人心理学の理論的特徴として、①目的論、②全体論、③対人関係論、④認知論が挙げられる。また、アドラーの人格理論では、個人の目標志向性や独自性、自己決定を表すものの見方や考え方、生き方をライフスタイルと呼んでいる。アドラーの理論は、集団心理療法や家族療法、短期療法の先駆になっており、育児・教育分野への貢献もみられる。\nウ　E.H. エリクソンは、人が生まれてから死に至るまでのパーソナリティの生涯発達のプロセスを、漸成発達という考え方を用いて理論化し、人間の一生をアイデンティティと呼んで、八つの発達段階に区別している。各発達段階は、段階ごとの発達主題によって特徴付けられている。児童期（学童期） の発達主題は、「勤勉性対劣等感」とされ、この主題の解決によって「意志」を獲得すると考えられている。\nエ　土居健郎は、精神分析過程で観察される依存現象として「甘え」に注目し、日本人の精神構造、社会文化構造、精神病理一般を理解するための鍵概念として用いた。甘えは、母親的対象に一体化を求めて結び付こうとする、乳幼児期に特有の欲動であり、甘えが満たされないと「すねる」、「ひがむ」などの心情が生まれる。さらに、こうした発達早期の甘えの抑圧や欠如は、知的発達症や自閉スペクトラム症などの神経発達症の基礎を形成する。",
