    "difficulty": 3,
    "question": "教育評価に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\nA　認定評価とは、学年や単元の初めに、その学習に対する準備がどの程度できているかを把握するために行う評価である。一方、単元や1時間の授業における指導の途中で、教師が子どもたちの様子から、授業が成功しているかどうかを点検するために行う評価を、診断的評価と呼ぶ。診断的評価を通じ、教師は授業の中で、自分の授業が狙いどおりに展開しているかを評価し、子どもたちへの支援を行ったり、授業計画や展開を修正したりすることができる。\nB　子どもが属している集団の成績を基準として、集団内での子どもたちの位置や序列によって評価を行う方法を総括的評価と呼ぶ。総括的評価では、正規分布曲線を基に、その配分率に従って子どもの成績を振り分ける。総括的評価を基にした指導過程として、B.S. ブルームの完全習得学習が知られている。完全習得学習は、全ての子どもに確かな学力を保障することを主張するもので、教師は正規分布の上位層を目標に、子どもに対して様々な働き掛けを行う。\nC　目標に準拠した評価は、子どもの学習の達成度を教育目標に照らして評価する方法であり、知識・技能のような基礎学力に限定された到達目標を設定し、評価を行う。したがって、目標に準拠した評価では、思考力や主体性を含む高次の学力についての評価は含まれない。目標に準拠した評価を行う際は、何を評価するのかを具体的に示す「評価基準」と、評価対象の子どもがどの程度の段階であるかを判断する根拠を示す「評価規準」の二つが必要となる。\nD　指導と評価の一体化とは、指導と評価が別物ではなく、表裏一体の関係にあることを意味しており、評価の結果が、指導の改善に生かされることが求められる。この考え方に基づけば、評価は、授業の目標に照らして行われる必要がある。授業の目標は、子どもたちに獲得されなければならない内容と能力を実体的に明示した到達目標と、「自ら解決する態度を養う」といった目指すべき方向を示した方向目標に区別することができる。",
