      "イ": "評価の結果を指導の改善につなげるのが指導と評価の一体化である。授業の目標には、達成すべき内容を示すものと方向を示すものがある。",
      "ウ": "指導前の準備状況を把握するのが診断的評価で、過程で改善に使うのが形成的評価である。集団内の位置で評価する方式は相対評価に当たる。",
