    "question": "次は、E. デュルケムの学説に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nE. デュルケムは、『社会学的方法の規準』において、「［A］とは、固定化されていると否とを問わず、個人のうえに外部的な拘束をおよぼすことができ、さらにいえば、固有の存在をもちながら所与の社会の範囲内に一般的にひろがり、その個人的な表現物からは独立しているいっさいの行為様式のことである」と書いた。そして、個人から独立して外部的拘束を及ぼす［A］については［B］のように科学的に考察することを、社会学の第一の方法的規準とした。\n\n最初の著作である『社会分業論』 では、人口が増加し、分業がより複雑に展開するようになると、それまでの個々の村落や部族が並列して環節的な構造を成し、単純に結び付いていたような段階から、それぞれの単位が解体していき、より広い範囲での社会的分業が成立し、以前とは違って個々の単位が限られた機能を果たして他と互いに補い合うような［C］の段階へと進んでいく、と述べた。\n\n一方で、分業は病理学的諸形態を呈することがあり、中でも経済生活は法的・道徳的無規制状態（アノミー） に置かれているとし、その終息のために、欠落した諸準則の体系を構築できる集団である［D］が形成されなければならないとした。［D］は道徳的影響力をもち、個人のエゴイズムを抑制し、個人の心のうちに生き生きとした共同連帯の感情を絶やさぬようにし、弱肉強食の法則が商工業上の諸関係に露骨に適用されないようにすることが可能であるとしている。\n\n各選択肢はA、B、C、Dの順。",
